package local.m13.home;

import android.app.*;
import android.content.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** App-local remote keyboard; never changes or replaces the system IME. */
public final class TvSearchKeyboard {
    private static TvSearchKeyboard active;
    private final Activity owner;private final EditText destination,input;private final Runnable search;private final Dialog dialog;
    private final Handler ui=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final LinearLayout candidates;private final TextView candidateHint;private final ArrayList<String> names=new ArrayList<String>();private boolean closed;private int generation;
    public static void bind(final Activity a,final EditText field,final Runnable search){field.setShowSoftInputOnFocus(false);field.setPadding(TvUi.dp(a,16),0,TvUi.dp(a,16),0);GradientDrawable bg=new GradientDrawable();bg.setColor(0xff102b4d);bg.setCornerRadius(TvUi.dp(a,12));bg.setStroke(TvUi.dp(a,1),0xff396a94);field.setBackground(bg);field.setBackgroundTintList(null);field.setOnClickListener(new View.OnClickListener(){public void onClick(View v){open(a,field,search);}});field.setOnKeyListener(new View.OnKeyListener(){public boolean onKey(View v,int code,KeyEvent e){if(code==23||code==66){if(e.getAction()==KeyEvent.ACTION_UP)open(a,field,search);return true;}return false;}});}
    private static void open(Activity a,EditText field,Runnable search){if(active!=null&&!active.closed)return;((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(field.getWindowToken(),0);active=new TvSearchKeyboard(a,field,search);}
    public static void closeFor(Activity a){if(active!=null&&active.owner==a)active.dialog.dismiss();}
    private int dp(int n){return TvUi.dp(owner,n);}
    private TextView text(String s,int size,int color){TextView t=new TextView(owner);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
    private TextView key(LinearLayout row,String label,final Runnable action){final TextView b=text(label,17,BlueRedTheme.TEXT);b.setGravity(Gravity.CENTER);b.setId(View.generateViewId());b.setFocusable(true);b.setClickable(true);b.setBackground(surface(false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(42),1);p.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(b,p);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){action.run();}});b.setOnFocusChangeListener(new View.OnFocusChangeListener(){public void onFocusChange(View v,boolean focus){b.setBackground(surface(focus));b.setTextColor(focus?BlueRedTheme.DARK:BlueRedTheme.TEXT);}});return b;}
    private GradientDrawable surface(boolean focus){GradientDrawable bg=focus?BlueRedTheme.focus(dp(10)):new GradientDrawable();if(!focus){bg.setColor(0xff24476f);bg.setCornerRadius(dp(10));}else bg.setStroke(dp(2),BlueRedTheme.TEXT);return bg;}
    private TvSearchKeyboard(Activity a,EditText original,Runnable callback){owner=a;destination=original;search=callback;dialog=new Dialog(a);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(dp(28),dp(20),dp(28),dp(20));root.setBackground(BlueRedTheme.background(0));TextView title=new BlueRedTheme.BrandText(a);title.setText("LibreTV  ·  搜索");title.setTextSize(25);root.addView(title,new LinearLayout.LayoutParams(-1,dp(42)));
        input=new EditText(a);input.setSingleLine(true);input.setShowSoftInputOnFocus(false);input.setTextSize(22);input.setTextColor(BlueRedTheme.TEXT);input.setHintTextColor(BlueRedTheme.FAINT);input.setHint("输入片名、拼音或首字母，例如 lldq");input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});input.setText(original.getText());input.setSelection(input.length());input.setPadding(dp(14),0,dp(14),0);input.setBackground(surface(false));root.addView(input,new LinearLayout.LayoutParams(-1,dp(52)));
        candidateHint=text("本地片名联想 · 输入两个字母后显示",12,BlueRedTheme.MUTED);root.addView(candidateHint,new LinearLayout.LayoutParams(-1,dp(28)));candidates=new LinearLayout(a);root.addView(candidates,new LinearLayout.LayoutParams(-1,dp(50)));
        View first=null;for(String chars:new String[]{"1234567890","QWERTYUIOP","ASDFGHJKL","ZXCVBNM"}){LinearLayout row=new LinearLayout(a);for(int n=0;n<chars.length();n++){final String value=chars.substring(n,n+1).toLowerCase(Locale.US);TextView b=key(row,chars.substring(n,n+1),new Runnable(){public void run(){insert(value);}});if(first==null)first=b;}root.addView(row);}
        LinearLayout actions=new LinearLayout(a);key(actions,"退格",new Runnable(){public void run(){int start=Math.min(input.getSelectionStart(),input.getSelectionEnd()),end=Math.max(input.getSelectionStart(),input.getSelectionEnd());if(start<0)return;if(start!=end)input.getText().delete(start,end);else if(start>0)input.getText().delete(input.getText().toString().offsetByCodePoints(start,-1),start);}});key(actions,"清空",new Runnable(){public void run(){input.setText("");}});key(actions,"空格",new Runnable(){public void run(){insert(" ");}});key(actions,"中文输入",new Runnable(){public void run(){destination.setText(input.getText());destination.setSelection(destination.length());dialog.dismiss();destination.setShowSoftInputOnFocus(true);destination.requestFocus();destination.postDelayed(new Runnable(){public void run(){((InputMethodManager)owner.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(destination,InputMethodManager.SHOW_IMPLICIT);}},100);}});key(actions,"搜索",new Runnable(){public void run(){submit(input.getText().toString());}});root.addView(actions);TextView hint=text("方向键选字 · 确认键输入 · 选中文片名直接搜索 · 返回取消",12,BlueRedTheme.FAINT);root.addView(hint,new LinearLayout.LayoutParams(-1,dp(28)));
        input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){suggest();}public void afterTextChanged(Editable e){}});input.setOnEditorActionListener(new TextView.OnEditorActionListener(){public boolean onEditorAction(TextView v,int action,KeyEvent event){if(action==3||action==6){submit(input.getText().toString());return true;}return false;}});
        dialog.setContentView(root);dialog.setOnDismissListener(new DialogInterface.OnDismissListener(){public void onDismiss(DialogInterface d){closed=true;generation++;worker.shutdownNow();ui.removeCallbacksAndMessages(null);if(active==TvSearchKeyboard.this)active=null;}});Window window=dialog.getWindow();window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);window.setBackgroundDrawableResource(android.R.color.transparent);dialog.show();int width=Math.min(dp(960),a.getResources().getDisplayMetrics().widthPixels-dp(64));window.setLayout(width,-2);if(first!=null)first.requestFocus();suggest();
    }
    private void insert(String value){int start=Math.max(0,input.getSelectionStart()),end=Math.max(0,input.getSelectionEnd());input.getText().replace(Math.min(start,end),Math.max(start,end),value);}
    private void submit(String word){if(word.trim().isEmpty()){Toast.makeText(owner,"请先输入片名或首字母",0).show();return;}destination.setText(word.trim());destination.setSelection(destination.length());dialog.dismiss();search.run();}
    private final Runnable lookup=new Runnable(){public void run(){final int request=generation;final String word=input.getText().toString().trim();if(word.length()<2)return;worker.submit(new Runnable(){public void run(){List<String> result;try{result=LibreTvTitleIndex.get(owner).suggest(word,4);}catch(Exception e){result=Collections.emptyList();}final List<String> found=result;ui.post(new Runnable(){public void run(){if(closed||request!=generation)return;names.clear();names.addAll(found);candidates.removeAllViews();candidateHint.setText(found.isEmpty()?"没有本地联想，可直接搜索当前输入":"本地片名联想 · 选择后直接搜索");for(final String name:found){TextView b=key(candidates,name,new Runnable(){public void run(){submit(name);}});b.setTextSize(14);b.setSingleLine();b.setEllipsize(TextUtils.TruncateAt.END);}}});}});}};
    private void suggest(){generation++;ui.removeCallbacks(lookup);names.clear();candidates.removeAllViews();candidateHint.setText(input.length()<2?"本地片名联想 · 输入两个字母后显示":"正在查找本地片名…");ui.postDelayed(lookup,240);}
    public static JSONObject diagnostics()throws Exception{return active==null?new JSONObject().put("showing",false):new JSONObject().put("showing",true).put("draft",active.input.getText().toString()).put("suggestions",new JSONArray(active.names));}
}
